UPDATE public.srmap_events_cache
SET
  content = '<p><a href="https://www.srmap.edu.in/seas/electrical-and-electronics-engineering/">The Department of  <span class="breadcrumb_last" aria-current="page">Electrical and Electronics Engineering </span></a>at SRM University-AP is set to host the <strong>1st International Conference on Next-Generation Energy and Mobility Technologies (NGEMT &#8211; 2026)</strong> on September 24-25, 2026. Convened by Dr Tarkeshwar Mahto, alongside co-conveners Dr Somesh Vinayak Tewari and Dr Ramanjaneya Reddy U, the conference invites prospective authors to submit original, unpublished research. The academic discourse will focus on pioneering advancements across five distinct tracks: Smart Grids and Energy Systems; Modern Control Techniques in Energy and Mobility Solutions; Next-Gen Communication Systems for Energy and E-Mobility; AI, IoT and Cybersecurity in Energy and Mobility; and Case Studies, Pilots, and Industrial Applications.</p>
<p>Peer-reviewed and selected papers from the conference are planned for publication in Springer’s prestigious, Scopus-indexed &#8220;<em>Lecture Notes in Electrical Engineering</em>&#8221; series. Researchers, academicians, and industry participants are encouraged to submit their manuscripts before the final deadline on July 15, 2026.</p>
<p>For further details regarding the event, fee structures, and submission guidelines, interested participants can contact conf.ngemt@srmap.edu.in or visit the event <a href="https://www.srmap.edu.in/ngemt-2026/">website.</a></p>',
  venue = NULL,
  organizer = 'Department of Electrical and Electronics Engineering',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146058;

UPDATE public.srmap_events_cache
SET
  content = '<p><img loading="lazy" decoding="async" class="size-full wp-image-146104 alignleft" src="https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-scaled.jpg" alt="terrathon" width="500" height="707" srcset="https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-scaled.jpg 1811w, https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-212x300.jpg 212w, https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-724x1024.jpg 724w, https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-768x1086.jpg 768w, https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-1086x1536.jpg 1086w, https://events.srmap.edu.in/wp-content/uploads/2026/07/TerraThon-2026-Onepage-Flyer-1448x2048.jpg 1448w" sizes="(max-width: 500px) 100vw, 500px" /></p>
<p><a href="https://www.srmap.edu.in/seas/environmental-science-and-engineering/">The Department of Environmental Science &amp; Engineering</a> at SRM University-AP is organising <strong>TerraThon 2026 Sustainability Sprint</strong>, a fast-paced sustainability hackathon designed to empower students and professionals to develop innovative solutions for real-world environmental challenges. Scheduled to take place at the APJ Abdul Kalam Auditorium, this event invites teams of 3 to 5 members—including undergraduate and postgraduate students from all disciplines, environmental organizations, and sustainable technology developers—to collaborate, learn from experts, and transform creative ideas into actionable environmental solutions. Participants will also benefit from expert mentorship, networking opportunities, complimentary food and accommodation, and a campus tour.</p>
<p><strong>Challenge Themes</strong></p>
<ul>
<li><strong>Smart Environmental Intelligence</strong>: Focusing on AI, IoT, digital sustainability, and smart monitoring.</li>
<li><strong>Water for the Future</strong>: Addressing water treatment, water reuse, and solutions for tracking and removing emerging contaminants.</li>
<li><strong>Climate &amp; Net-Zero Solutions</strong>: Exploring climate action, carbon management, and decarbonisation.</li>
<li><strong>Sustainable Materials &amp; Clean Energy</strong>: Dedicated to advanced materials, energy storage, and environmental applications.</li>
<li><strong>Circular Bioeconomy &amp; Resource Recovery</strong>: Centered on waste valorisation, circular economy, and resource recovery.</li>
</ul>
<p><strong>Important Dates</strong></p>
<ul>
<li><strong>Registration Start Date</strong>: June 30, 2026</li>
<li><strong>Registration Closing Date</strong>: September 15, 2026</li>
<li><strong>Event Date and Time</strong>: September 25, 2026, from 8:30 AM to 5:30 PM</li>
</ul>
<p>An array of rewards awaits outstanding performers, including a grand prize of ₹15,000 for the Champion Team, ₹10,000 for the First Runner-Up, and ₹5,000 for the Second Runner-Up, alongside specialized recognition through the Rising Sustainability Innovator Awards and the TerraThon Jury&#8217;s Choice Awards. For further coordination, queries can be directed to the event coordinators, Dr Nirav P. Raval, Dr Deep Raj, or Dr Narayanamoorthy Bhuvanendran.</p>',
  venue = 'APJ Abdul Kalam Auditorium',
  organizer = 'Department of Environmental Science and Engineering',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146103;

