SET
  content = '<p>The Department of Literature and Languages, Easwari School of Liberal Arts (ESLA), SRM University-<em>AP</em> is hosting the second edition of the Amaravati Literature Festival (ALF) on October 07-09, 2026.</p>
<p>The three-day literature festival is a pinnacle of literary creation, innovation and culture, bringing together a vibrant mix of authors, poets, translators, academics, and cultural icons.</p>
<p>The festival will feature panel discussions, art installations, craft exhibitions, and culinary experiences, making ALF a holistic cultural celebration. This pioneering initiative reflects SRM <em>AP</em>’s vision of education that extends beyond the classroom to the broader community.</p>
<p>Further details about ALF 2026 will be announced soon.</p>',
  venue = 'APJ Abdul Kalam Auditorium',
  organizer = 'Department of Literature and Languages',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146045;

