UPDATE public.srmap_events_cache
SET
  content = '<p>The Department of Environmental Science and Engineering is organising <strong>Nano2Nature (N2N) Research Bootcamp</strong>, a research-oriented, hands-on academic outreach workshop designed to introduce students to emerging applications of nanotechnology, environmental science, water research, and energy applications.</p>
<p>The event aims to provide participants with practical training and exposure to cutting-edge tools, techniques, and innovative approaches for addressing critical environmental challenges.</p>
<p><strong>Key Highlights</strong></p>
<ul>
<li>Learn from domain experts working in Nano × Environment, Energy and Water research.</li>
<li>Experience hands-on wet-lab demonstrations covering nanomaterial synthesis and characterization, water quality analysis, contaminant detection, and electrochemical studies.</li>
<li>Visit environmental engineering laboratories and experience live demonstrations of sophisticated research instruments at the Central Research Facility (CRF).</li>
<li>Participate in a quiz competition based on nano-environment concepts, lectures, and demonstrations.</li>
<li>Network with faculty members, researchers, experts, and fellow students.</li>
</ul>
<p>The research bootcamp is open to motivated undergraduate and postgraduate students:</p>
<p><strong>B.Sc. &amp; M.Sc. Students:</strong> Environmental Science, Chemistry, Biology, Biochemistry, Biotechnology, Microbiology, Physics, and allied science disciplines.</p>
<p><strong>B.Tech. Students:</strong> Environmental Engineering, Civil Engineering, Chemical Engineering, Biotechnology, Agricultural Engineering, and allied engineering branches.</p>
<p><strong>Registration Deadline: September 30, 2026</strong></p>',
  venue = NULL,
  organizer = 'Department of Environmental Science and Engineering',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146309;

UPDATE public.srmap_events_cache
SET
  content = '<p><img loading="lazy" decoding="async" class="size-full wp-image-146097 alignleft" src="https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp.jpg" alt="psb-bootcamp" width="500" height="648" srcset="https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp.jpg 1229w, https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp-231x300.jpg 231w, https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp-790x1024.jpg 790w, https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp-768x995.jpg 768w, https://events.srmap.edu.in/wp-content/uploads/2026/07/psb-bootcamp-1185x1536.jpg 1185w" sizes="(max-width: 500px) 100vw, 500px" />The Paari School of Business at SRM University-<em>AP</em>, in partnership with the Academy of Management Community Accelerator and the Kozai Group, Inc., is organising an intensive <strong>Early Career Researchers&#8217; Publishing Boot Camp</strong>. Led by distinguished program leaders Dr Allan Bird and Dr Elizabeth L. Rose, this intensive workshop offers comprehensive mentorship to refine close-to-submission manuscripts for top-tier journals.</p>
<p><strong>Key Features</strong></p>
<ul>
<li><strong>Expert Mentorship</strong>: Individual guidance and peer review sessions from senior business scholars conducted before, during, and after the camp.</li>
<li><strong>Dedicated Writing Blocks</strong>: Over 20 hours of structured writing time coupled with daily SMART goal-setting progress check-ins.</li>
<li><strong>Publishing Strategies</strong>: Practical mini-lectures on crafting compelling introductions, strengthening literature reviews, navigating editor feedback, and avoiding desk rejections.</li>
<li><strong>Pre-Boot Camp Symposium</strong>: Complimentary access to a One-Day National Symposium on reimagining management through AI, featuring a keynote by Dr Soumitra Dutta.</li>
</ul>
<p>The program is strictly limited to 20 participants, targeting doctoral students close to graduation, postdocs, and junior faculty.</p>
<p>The participation fee also includes complimentary registration for the pre-boot camp event on October 24, 2026, a One-Day National Symposium titled &#8220;<strong>Advancing Management Knowledge in the AI Era: Research Frontiers and Future Directions</strong>,&#8221; featuring a keynote address by Dr Soumitra Dutta</p>
<p>To apply, candidates must submit a three-page manuscript outline and a one-page benefit statement, which will be evaluated based on quality, contribution, and readiness.</p>
<p><strong>Important Dates</strong></p>
<ul>
<li><strong>Application Deadline</strong>: August 6, 2026</li>
<li><strong>Pre-Boot Camp Symposium</strong>: October 24, 2026</li>
<li><strong>Boot Camp Execution</strong>: October 25–29, 2026</li>
</ul>
<p>For submission links and detailed information, prospective applicants can visit the registration portal at <a href="https://www.kozaigroup.com/ecr-publishing-bootcamp-india/">www.kozaigroup.com/ecr-publishing-bootcamp-india/</a>.</p>
