UPDATE public.srmap_events_cache
SET
  content = '<p><a href="https://www.srmap.edu.in/seas/mechanical-engineering/"><img loading="lazy" decoding="async" class="size-full wp-image-146055 alignleft" src="https://events.srmap.edu.in/wp-content/uploads/2026/07/AIRIM-2026-flyer.png" alt="airim-flyer" width="500" height="625" srcset="https://events.srmap.edu.in/wp-content/uploads/2026/07/AIRIM-2026-flyer.png 756w, https://events.srmap.edu.in/wp-content/uploads/2026/07/AIRIM-2026-flyer-240x300.png 240w" sizes="(max-width: 500px) 100vw, 500px" />The Department of Mechanical Engineering</a> at SRM University-<em>AP</em>, Amaravati, is organising the <strong>International Conference on AI, Robotics and Intelligent Manufacturing (AIRIM-2026)</strong> from November 5 to 7, 2026. This premier global platform aims to foster innovation and collaboration in robotics, AI, and advanced manufacturing. The event will feature invited talks by esteemed international and national keynote speakers, paper and poster presentations, industry stalls, and a hands-on robotic workshop. Attendees will also have the opportunity to participate in guided lab visits to the Advanced Robotics Lab and Manufacturing facility.</p>
<p>AIRIM-2026 invites researchers, professionals, and students to submit original research and review articles across three main tracks: Robot Modeling, Control, and Autonomous Systems; Intelligent Robotics, Perception, and Human Interaction; and Industry 4.0 and Digital Manufacturing Systems. Selected papers will be considered for open-access publication in Atlantis Press proceedings by Springer Nature.</p>
<ul>
<li>Prospective authors must submit a two-page abstract to conf.airim2026@srmap.edu.in by August 10, 2026.</li>
<li>Intimation of acceptance will occur by August 25, 2026</li>
<li>full paper submissions due by September 10, 2026.</li>
</ul>',
  venue = NULL,
  organizer = 'Department of Mechanical Engineering',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146054;

UPDATE public.srmap_events_cache
SET
  content = '<p><img loading="lazy" decoding="async" class="size-full wp-image-146085 alignleft" src="https://events.srmap.edu.in/wp-content/uploads/2026/07/UNITES-2026.jpg" alt="unites-2026" width="500" height="844" srcset="https://events.srmap.edu.in/wp-content/uploads/2026/07/UNITES-2026.jpg 762w, https://events.srmap.edu.in/wp-content/uploads/2026/07/UNITES-2026-178x300.jpg 178w, https://events.srmap.edu.in/wp-content/uploads/2026/07/UNITES-2026-607x1024.jpg 607w" sizes="(max-width: 500px) 100vw, 500px" />SRM University-AP is gearing up to host <strong>UNITES 2026</strong>, a Conference on Converging Frontiers in Science and Technology, from December 27 to 29, 2026. Organised by the <a href="https://www.srmap.edu.in/research/centre-for-inter-disciplinary-research/">Centre for Interdisciplinary Research (CIDR)</a>, the gathering will take place at the APJ Abdul Kalam Auditorium in Amaravati. Centered around the theme &#8220;Physics at the Interfaces of Matter, Light and Life,&#8221; the event aims to unite interdisciplinary trends in emerging science. The academic discourse will delve into focus areas such as Advanced Materials and Light-Matter Systems alongside Complex and Living Physical Systems.</p>
<p>There will be popular and invited talks, contributed talks, poster sessions, panel discussions, and ample networking opportunities, to foster academic engagement and participation.</p>
<p>Convened by Dr Kiran Mangalampalli and Dr Sabyasachi Mukhopadhyay, UNITES 2026 offers comprehensive registration tiers that include full hospitality, a registration kit, and access to all technical sessions.</p>
<ul>
<li>A merit-based transport allowance will be provided to 300 selected students</li>
<li>Participants will have the opportunity to win prizes and awards worth ₹5,00,000.</li>
<li>Furthermore, selected papers presented at the conference will be considered for peer-reviewed publication in prestigious international journals</li>
</ul>
<p>&nbsp;</p>
<p>For detailed registration, abstract submission, and further updates, prospective participants are encouraged to visit <a href="https://www.srmap.edu.in/unites-2026/">https://www.srmap.edu.in/unites-2026/</a>.</p>',
  venue = NULL,
  organizer = 'Centre for Interdisciplinary Research (CIDR)',
  registration_url = NULL,
  registration_label = NULL
WHERE id = 146083;